        calculate_total(cdt, cdn);
    },

    qty: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    },

    rate: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    }
});

function calculate_labour_row_total(cdt, cdn) {
    let row = locals[cdt][cdn];

    let total = (row.qty || 0) * (row.rate || 0);

    frappe.model.set_value(cdt, cdn, 'total', total);
}

frappe.ui.form.on('Revive Job Card', {
    refresh(frm) {
        calculate_spares_total(frm);
        creat_sales_invoice(frm);
        // make_payment_entry(frm);
    },

    spare_total(frm) {
        calculate_grand_total(frm);
    },

    labour_total(frm) {
        calculate_grand_total(frm);
    },
     grand_total(frm) {
        calculate_discount(frm);
    },

    discount_amount(frm) {
        if (!frm._calculating_discount) {
            calculate_discount(frm, 'amount');
        }
    },

    discount_percentage(frm) {
        if (!frm._calculating_discount) {
            calculate_discount(frm, 'percentage');
        }
    }

});

frappe.ui.form.on('Revive Job Card Spares Used', {
    total(frm, cdt, cdn) {
        calculate_spares_total(frm);
    },
    spares_used_remove(frm, cdt, cdn) {
        calculate_spares_total(frm);
    },
    // item: function(frm, cdt, cdn) {
    //     calculate_spare_total(cdt, cdn);
    // },
    item: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.item) {
            return;
        }

        frappe.db.get_value(
            "Item Price",
            {
                item_code: row.item,
                price_list: "Standard Selling"
            },
            "price_list_rate"
        ).then(r => {

            if (r.message && r.message.price_list_rate) {
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "rate",
                    r.message.price_list_rate
                );
            } else {
                frappe.model.set_value(cdt, cdn, "rate", 0);

                frappe.alert(
                    __("No selling price found for {0} in Standard Selling.", [row.item])
                );
            }
            calculate_spare_total(cdt, cdn);
        });

    },

    qty: function(frm, cdt, cdn) {
        calculate_spare_total(cdt, cdn);
    },

    rate: function(frm, cdt, cdn) {
        calculate_spare_total(cdt, cdn);
    }
});


function calculate_spare_total(cdt, cdn) {
    let row = locals[cdt][cdn];

    let total = (row.qty || 0) * (row.rate || 0);

    frappe.model.set_value(cdt, cdn, 'total', total);
}

frappe.ui.form.on('Revive Job Card Repairs Done', {
    total(frm, cdt, cdn) {
