frappe.ui.form.on("Revive Job Card", {

    refresh(frm) {
        // Make sure barcode field is ready
        if (frm.fields_dict.scan_barcode) {
            frm.fields_dict.scan_barcode.$input.attr(
                "placeholder",
                "Scan barcode..."
            );
        }
    },

    scan_barcode(frm) {

        const barcode = frm.doc.scan_barcode;

        if (!barcode) {
            return;
        }

        // ---------------------------------------------------------
        // Scan barcode using ERPNext standard barcode API
        // ---------------------------------------------------------

        frappe.call({
            method: "erpnext.stock.utils.scan_barcode",
            args: {
                search_value: barcode
            },

            freeze: true,
            freeze_message: __("Looking up item..."),

            callback(r) {

                // Clear scan field immediately
                frm.set_value("scan_barcode", "");

                const data = r.message;

                if (!data || !data.item_code) {

                    frappe.msgprint({
                        title: __("Item Not Found"),
                        message: __(
                            "No item was found for barcode <b>{0}</b>.",
                            [barcode]
                        ),
                        indicator: "red"
                    });

                    return;
                }

                const item_code = data.item_code;

                // -------------------------------------------------
                // Check whether item already exists in spares_used
                // -------------------------------------------------

                let existing_row = (frm.doc.spares_used || []).find(
                    row => row.item === item_code
                );

                if (existing_row) {

                    // -------------------------------------------------
                    // Existing item → increase quantity
                    // -------------------------------------------------

                    existing_row.qty = flt(existing_row.qty || 0) + 1;

                    existing_row.total =
                        flt(existing_row.qty) *
                        flt(existing_row.rate || 0);

                    calculate_spares_total(frm)
                    frm.refresh_field("spares_used");

                    frappe.show_alert({
                        message: __(
                            "{0} quantity increased to {1}",
                            [
                                item_code,
                                existing_row.qty
                            ]
                        ),
                        indicator: "green"
                    });

                    return;
                }

                // -------------------------------------------------
                // New item → add new row
                // -------------------------------------------------

                let row = frm.add_child("spares_used");

                row.item = item_code;
                row.qty = 1;

                // -------------------------------------------------
                // Fetch selling price
                // -------------------------------------------------

                // frappe.db.get_value(
                //     "Item Price",
                //     {
                //         item_code: item_code,
                //         price_list: "Standard Selling"
                //     },
                //     "price_list_rate"
                // ).then(r => {
                
                //     if (r.message && r.message.price_list_rate) {
                
                //         row.rate = flt(r.message.price_list_rate);
                
                //     } else {
                
                //         row.rate = 0;
                
                //         frappe.show_alert({
                //             message: __(
                //                 "No selling price found for {0}.",
                //                 [item_code]
                //             ),
                //             indicator: "orange"
                //         });
                //     }
                
                //     row.total =
                //         flt(row.qty || 0) *
                //         flt(row.rate || 0);
                
                //     frm.refresh_field("spares_used");
                
                //     frappe.show_alert({
                //         message: __(
                //             "{0} added to Spares.",
                //             [item_code]
                //         ),
                //         indicator: "green"
                //     });
                // });
                
                // -------------------------------------------------
                // Fetch Item Name + Selling Price
                // -------------------------------------------------

                    Promise.all([
                        frappe.db.get_value(
                            "Item",
                            item_code,
                            "item_name"
                        ),
                    
                        frappe.db.get_value(
                            "Item Price",
                            {
                                item_code: item_code,
                                price_list: "Standard Selling"
                            },
                            "price_list_rate"
                        )
                    ]).then(([item_response, price_response]) => {
                    
                        // -----------------------------
                        // Item Name
                        // -----------------------------
                    
                        if (item_response.message) {
                            row.name1 = item_response.message.item_name || "";
                        } else {
                            row.name1 = "";
                        }
                    
                        // -----------------------------
                        // Selling Price
                        // -----------------------------
                    
                        if (
                            price_response.message &&
                            price_response.message.price_list_rate
                        ) {
                            row.rate = flt(
                                price_response.message.price_list_rate
                            );
                        } else {
                    
                            row.rate = 0;
                    
                            frappe.show_alert({
                                message: __(
                                    "No selling price found for {0}.",
                                    [item_code]
                                ),
                                indicator: "orange"
                            });
                        }
                    
                        // -----------------------------
                        // Calculate Total
                        // -----------------------------
                    
                        row.total =
                            flt(row.qty || 0) *
                            flt(row.rate || 0);
                    
                        // -----------------------------
                        // Refresh Child Table
                        // -----------------------------
                    
                        frm.refresh_field("spares_used");
                        calculate_spares_total(frm)
                    
                        frappe.show_alert({
                            message: __(
                                "{0} added to Spares.",
                                [item_code]
                            ),
                            indicator: "green"
                        });
                    });

                frm.refresh_field("spares_used");
                
            },

            error() {

                frm.set_value("scan_barcode", "");

                frappe.msgprint({
                    title: __("Barcode Error"),
                    message: __(
                        "Unable to find an item using barcode <b>{0}</b>.",
                        [barcode]
                    ),
                    indicator: "red"
                });
            }
        });
    }
});

function calculate_spares_total(frm) {
    let total = 0;

    (frm.doc.spares_used || []).forEach(row => {
        total += flt(row.total);
    });

    frm.set_value('spare_total', total);
    calculate_grand_total(frm)
}

function calculate_grand_total(frm) {
    let spare_total = flt(frm.doc.spare_total);
    let labour_total = flt(frm.doc.labour_total);

    frm.set_value('grand_total', spare_total + labour_total);
}

frappe.ui.form.on("Revive Job Card", {

    refresh(frm) {

        frm.add_custom_button(__("Make Advance Payment"), function () {

            // ---------------------------------------------------------
            // Customer validation
            // ---------------------------------------------------------

            if (!frm.doc.customer) {
                frappe.msgprint({
                    title: __("Customer Required"),
                    message: __("Please select a Customer first."),
                    indicator: "red"
                });
                return;
            }


            // ---------------------------------------------------------
            // Ask for amount
            // ---------------------------------------------------------

            frappe.prompt(
                [
                    {
                        fieldname: "amount",
                        fieldtype: "Currency",
                        label: __("Advance Amount"),
                        reqd: 1
                    }
                ],

                function (values) {

                    const amount = flt(values.amount);

                    if (amount <= 0) {
                        frappe.msgprint({
                            title: __("Invalid Amount"),
                            message: __("Advance amount must be greater than zero."),
                            indicator: "red"
                        });
                        return;
                    }


                    // -------------------------------------------------
                    // Open NEW Payment Entry
                    //
                    // Nothing is saved here.
                    // -------------------------------------------------

                    frappe.new_doc("Payment Entry", {}, function (pe_frm) {

                        // -------------------------------------------------
                        // Payment Type
                        // -------------------------------------------------

                        pe_frm.set_value(
                            "payment_type",
                            "Receive"
                        );


                        // -------------------------------------------------
                        // Party Type
                        // -------------------------------------------------

                        pe_frm.set_value(
                            "party_type",
                            "Customer"
                        );


                        // -------------------------------------------------
                        // Customer
                        //
                        // Setting the actual Link field causes ERPNext
                        // to execute its normal party fetching logic.
                        // -------------------------------------------------

                        pe_frm.set_value(
                            "party",
                            frm.doc.customer
                        );


                        // -------------------------------------------------
                        // Job Card
                        // -------------------------------------------------

                        pe_frm.set_value(
                            "custom_job_card",
                            frm.doc.name
                        );


                        // -------------------------------------------------
                        // Amount
                        // -------------------------------------------------

                        pe_frm.set_value(
                            "paid_amount",
                            amount
                        );

                        pe_frm.set_value(
                            "received_amount",
                            amount
                        );


                        // -------------------------------------------------
                        // Posting Date
                        // -------------------------------------------------

                        pe_frm.set_value(
                            "posting_date",
                            frappe.datetime.get_today()
                        );


                        // -------------------------------------------------
                        // Refresh fields
                        // -------------------------------------------------

                        pe_frm.refresh_fields();

                    });

                },

                __("Advance Payment"),

                __("Continue")
            );
        }, __("Payments"));
    }
});

