function open_issue_stock_dialog(frm) {

    let items = [];

    const dialog = new frappe.ui.Dialog({

        title: __("Issue Stock"),

        size: "extra-large",

        fields: [

            {
                fieldname: "item_code",
                label: __("Search Part"),
                fieldtype: "Link",
                options: "Item",
                // reqd: 1,

                get_query() {
                    return {
                        filters: {
                            disabled: 0,
                            is_stock_item: 1
                        }
                    };
                },

                onchange() {
                    update_item_details(dialog);
                }
            },
            
            {
                fieldname: "item_name",
                label: __("Part Name"),
                fieldtype: "Data",
                read_only: 1
            },

            {
                fieldname: "available_qty",
                label: __("Available Qty"),
                fieldtype: "Float",
                read_only: 1
            },

            {
                fieldname: "issue_qty",
                label: __("Issue Qty"),
                fieldtype: "Float",
                // reqd: 1,
                default: 1
            },
            {
                fieldname: "uom",
                label: __("UOM"),
                fieldtype: "Link",
                options: "UOM",
                // reqd: 1,
            
                get_query() {
                    const item_code = dialog.get_value("item_code");
            
                    if (!item_code) {
                        return {};
                    }
            
                    return {
                        query: "rarison_motors.api.revive_job_card.get_item_uoms",
                        filters: {
                            item_code: item_code
                        }
                    };
                },
            
                onchange() {
                    update_uom_details(dialog);
                }
            },

            {
                fieldname: "rate",
                label: __("Selling Rate"),
                fieldtype: "Currency",
                read_only: 1
            },

            {
                fieldname: "add_part",
                fieldtype: "Button",
                label: __("Add Part"),
                click() {
                    add_item_to_list(dialog, items);
                }
            },

            {
                fieldname: "items_html",
                fieldtype: "HTML"
            },
            
            {
                fieldname: "conversion_factor",
                fieldtype: "Float",
                hidden: 1
            },
            {
                fieldname: "stock_uom",
                fieldtype: "Data",
                hidden: 1
            },
        ],

        primary_action_label: __("Issue Stock"),

        primary_action() {

            if (!items.length) {
                frappe.msgprint({
                    title: __("No Items"),
                    message: __("Please add at least one part."),
                    indicator: "orange"
                });

                return;
            }

            show_issue_confirmation(frm, dialog, items);
        }
    });


    dialog.show();

    render_items_table(dialog, items);
}


async function update_item_details(dialog) {

    const item_code = dialog.get_value("item_code");

    if (!item_code) {
        dialog.set_value("available_qty", 0);
        dialog.set_value("rate", 0);
        return;
    }

    try {

        const result = await frappe.call({
            method: "rarison_motors.api.revive_job_card.get_item_details",
            args: {
                item_code: item_code
            }
        });

        if (!result.message) {
            return;
        }
        
        dialog.set_value(
            "item_name",
            result.message.item_name || ""
        );

        dialog.set_value(
            "available_qty",
            result.message.available_qty || 0
        );
        
        dialog.set_value(
            "uom",
            result.message.stock_uom || ""
        );

        dialog.set_value(
            "rate",
            result.message.rate || 0
        );
        
        dialog.set_value(
            "stock_uom",
            result.message.stock_uom || ""
        );

    } catch (error) {

        console.error(error);

        frappe.msgprint({
            title: __("Error"),
            message: __("Unable to fetch item details."),
            indicator: "red"
        });
    }
}


