function add_item_to_list(dialog, items) {

    const item_code = dialog.get_value("item_code");
    const item_name = dialog.get_value("item_name");
    const issue_qty = flt(dialog.get_value("issue_qty"));
    const uom = dialog.get_value("uom");
    const available_qty = flt(dialog.get_value("available_qty"));
    const conversion_factor =
        flt(dialog.get_value("conversion_factor")) || 1;
    const rate = flt(dialog.get_value("rate"));

    // ------------------------------------------------------------
    // Basic validation
    // ------------------------------------------------------------

    if (!item_code) {
        frappe.msgprint(__("Please select a part."));
        return;
    }

    if (!uom) {
        frappe.msgprint(__("Please select a UOM."));
        return;
    }

    if (issue_qty <= 0) {
        frappe.msgprint(__("Issue quantity must be greater than zero."));
        return;
    }

    if (conversion_factor <= 0) {
        frappe.msgprint(__("Invalid UOM conversion factor."));
        return;
    }

    // ------------------------------------------------------------
    // Convert entered quantity to stock UOM
    //
    // Example:
    // 1.75 Litre × 0.4 = 0.70 Nos
    // ------------------------------------------------------------

    const issue_stock_qty = issue_qty * conversion_factor;

    // ------------------------------------------------------------
    // Check available stock
    // available_qty is in stock UOM
    // ------------------------------------------------------------

    if (issue_stock_qty > available_qty + 0.000001) {

        const max_issue_qty = available_qty / conversion_factor;

        frappe.msgprint({
            title: __("Insufficient Stock"),

            message: __(
                "Available stock is {0} {1}. " +
                "You are trying to issue {2} {3}. " +
                "Maximum possible quantity is approximately {4} {3}."
            )
            .replace("{0}", available_qty)
            .replace("{1}", dialog.get_value("stock_uom") || "")
            .replace("{2}", issue_qty)
            .replace("{3}", uom)
            .replace("{4}", max_issue_qty.toFixed(3)),

            indicator: "red"
        });

        return;
    }

    // ------------------------------------------------------------
    // Check if same item + same UOM already exists
    // ------------------------------------------------------------

    const existing = items.find(
        row =>
            row.item === item_code &&
            row.uom === uom
    );

    if (existing) {

        const new_qty = existing.qty + issue_qty;

        const new_stock_qty =
            new_qty * conversion_factor;

        if (new_stock_qty > available_qty + 0.000001) {

            const max_issue_qty =
                available_qty / conversion_factor;

            frappe.msgprint({
                title: __("Insufficient Stock"),

                message: __(
                    "The total requested quantity for {0} " +
                    "would be {1} {2}. " +
                    "Available stock allows a maximum of approximately " +
                    "{3} {2}."
                )
                .replace("{0}", item_code)
                .replace("{1}", new_qty)
                .replace("{2}", uom)
                .replace("{3}", max_issue_qty.toFixed(3)),

                indicator: "red"
            });

            return;
        }

        existing.qty = new_qty;

        existing.stock_qty =
            new_qty * existing.conversion_factor;

        existing.total =
            new_qty * existing.rate;

    } else {
        
        items.push({
            item: item_code,
            item_name: dialog.get_value("item_name"),
            qty: issue_qty,
            uom: dialog.get_value("uom"),
            conversion_factor: flt(dialog.get_value("conversion_factor")) || 1,
            available_qty: available_qty,
            rate: rate,
            total: issue_qty * rate
        });
    }

    // ------------------------------------------------------------
    // Refresh table
    // ------------------------------------------------------------

    render_items_table(dialog, items);

    // ------------------------------------------------------------
    // Reset entry fields
    // ------------------------------------------------------------

    dialog.set_value("item_code", "");
    dialog.set_value("item_name", "");
    dialog.set_value("available_qty", 0);
    dialog.set_value("issue_qty", 1);
    dialog.set_value("uom", "");
    dialog.set_value("conversion_factor", 1);
    dialog.set_value("rate", 0);
    dialog.set_value("stock_uom", "");
}

function render_items_table(dialog, items) {

    let html = `
        <div style="margin-top: 15px;">

            <table class="table table-bordered">

                <thead>
                    <tr>
                        <th style="width:5%">#</th>
                        <th>Part No</th>
                        <th>Available</th>
                        <th>Issue Qty</th>
                        <th>Rate</th>
                        <th>Total</th>
                        <th style="width:5%"></th>
                    </tr>
                </thead>

                <tbody>
    `;

    let grand_total = 0;

    items.forEach((row, index) => {

        grand_total += flt(row.total);

        html += `
            <tr>

                <td>${index + 1}</td>

                <td>
                    <b>${frappe.utils.escape_html(row.item)}</b>
                    <br>
                    <small>${frappe.utils.escape_html(row.item_name || "")}</small>
                </td>

                <td>${flt(row.available_qty)}</td>

                <td>${flt(row.qty)}</td>

                <td>${format_currency(row.rate)}</td>

                <td>${format_currency(row.total)}</td>

                <td>
                    <button
                        class="btn btn-xs btn-danger remove-stock-item"
                        data-index="${index}">
                        <i class="fa fa-trash"></i>
                    </button>
                </td>

            </tr>
        `;
    });

    if (!items.length) {

        html += `
            <tr>
                <td colspan="7" class="text-center text-muted">
                    No parts added
                </td>
            </tr>
        `;
    }

    html += `
                </tbody>

                <tfoot>

                    <tr>
                        <td colspan="5" style="text-align:right">
                            <b>Grand Total</b>
                        </td>

                        <td>
                            <b>${format_currency(grand_total)}</b>
                        </td>

                        <td></td>
                    </tr>

                </tfoot>

            </table>

        </div>
    `;

    dialog.fields_dict.items_html.$wrapper.html(html);

    dialog.fields_dict.items_html.$wrapper
        .find(".remove-stock-item")
        .on("click", function () {

            const index = cint($(this).attr("data-index"));

            items.splice(index, 1);

            render_items_table(dialog, items);
        });
}


function show_issue_confirmation(frm, dialog, items) {

    const total_qty = items.reduce(
        (sum, row) => sum + flt(row.qty),
        0
    );

    frappe.confirm(

        __(
            "Are you sure you want to transfer {0} item quantities " +
            "to <b>Issued to Workshop - RM</b>?"
        ).replace("{0}", total_qty),

        () => {

            frappe.call({

                method: "rarison_motors.api.revive_job_card.issue_stock",

                freeze: true,

                freeze_message: __("Issuing stock..."),

                args: {
                    parent_doctype: frm.doctype,
                    parent_name: frm.docname,
                    // items: items.map(row => ({
                    //     item: row.item,
                    //     qty: row.qty
                    // }))
                    items: items.map(row => ({
                        item: row.item,
                        qty: row.qty,
                        uom: row.uom,
                        conversion_factor: row.conversion_factor
                    }))
                },

                callback(response) {

                    if (!response.message) {
                        return;
                    }

                    frappe.show_alert({
                        message: __(
                            "Stock issued successfully. Stock Entry: {0}"
                        ).replace(
                            "{0}",
                            response.message.stock_entry
                        ),
                        indicator: "green"
                    });

                    dialog.hide();

                    frm.reload_doc();
                }
            });
        }
    );
}

async function update_uom_details(dialog) {

    const item_code = dialog.get_value("item_code");
    const uom = dialog.get_value("uom");

    if (!item_code || !uom) {
        return;
    }

    try {

        const result = await frappe.call({
            method: "rarison_motors.api.revive_job_card.get_uom_details",
            args: {
                item_code: item_code,
                uom: uom
            }
        });

        if (!result.message) {
            return;
        }

        dialog.set_value(
            "conversion_factor",
            result.message.conversion_factor || 1
        );

        // Get selling price for the selected UOM
        await update_item_price(dialog);

    } catch (error) {

        console.error(error);

        frappe.msgprint({
            title: __("UOM Error"),
            message: __("Unable to determine UOM conversion."),
            indicator: "red"
        });
    }
}

async function update_item_price(dialog) {

    const item_code = dialog.get_value("item_code");
    const uom = dialog.get_value("uom");

    if (!item_code || !uom) {
        dialog.set_value("rate", 0);
        return;
    }

    try {

        const result = await frappe.call({
            method: "rarison_motors.api.revive_job_card.get_item_price",
            args: {
                item_code: item_code,
                uom: uom
            }
        });

        if (!result.message) {
            dialog.set_value("rate", 0);
            return;
        }

        dialog.set_value(
            "rate",
            flt(result.message.rate || 0)
        );

    } catch (error) {

        console.error(error);

        dialog.set_value("rate", 0);

        frappe.msgprint({
            title: __("Price Error"),
            message: __("Unable to fetch selling price."),
            indicator: "red"
        });
    }
}
